contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address receiver, uint amount) public payable {
        bool ownerCall = (msg.sender == address(this));
        bool reverted;
        uint beforeBalC = address(c).balance;
        uint beforeBalThis = address(this).balance;

        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldRevert = (receiver == address(0)) || (amount == 0) || (!ownerCall);

        assert(reverted == shouldRevert);

        if (!reverted) {
            assert((receiver != address(0)) && (amount > 0) && ownerCall);
            assert(address(c).balance == beforeBalC - amount);
            assert(address(this).balance == beforeBalThis + amount);
        }
    }

    receive() external payable {}
}

